-- 司机安全培训考试模块 PostgreSQL DDL
-- 说明：
-- 1. 所有业务表主键统一为 id bigint generated by default as identity。
-- 2. 关联字段仅建立普通索引，不创建外键约束。
-- 3. 枚举字段使用 varchar 存储，枚举定义写入 sys_dict_type / sys_dict_item。
-- 4. 所有业务表使用 is_del 标识逻辑删除，false 表示未删除，true 表示已删除。

BEGIN;

CREATE TABLE public.training_course (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    is_del bool NOT NULL DEFAULT false,
    course_name varchar(200) NOT NULL,
    training_type varchar(50) NOT NULL,
    introduction text,
    planned_learning_seconds integer NOT NULL,
    video_file_id varchar(128) NOT NULL,
    video_duration_seconds integer NOT NULL,
    status varchar(20) NOT NULL DEFAULT 'DRAFT',
    is_locked boolean NOT NULL DEFAULT false,
    created_by varchar(64) NOT NULL,
    created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by varchar(64) NOT NULL,
    updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT ck_training_course_learning_seconds_nonnegative
        CHECK (planned_learning_seconds >= 0 AND video_duration_seconds >= 0),
    CONSTRAINT ck_training_course_duration_consistent
        CHECK (planned_learning_seconds = video_duration_seconds)
);

COMMENT ON TABLE public.training_course IS '培训视频课程';
COMMENT ON COLUMN public.training_course.id IS '主键，自增';
COMMENT ON COLUMN public.training_course.is_del IS '是否删除：false-未删除，true-已删除';
COMMENT ON COLUMN public.training_course.course_name IS '课程名称';
COMMENT ON COLUMN public.training_course.training_type IS '培训类型，字典：training_type';
COMMENT ON COLUMN public.training_course.introduction IS '课程简介';
COMMENT ON COLUMN public.training_course.planned_learning_seconds IS '计划学习时长，单位秒；必须与视频实际时长一致';
COMMENT ON COLUMN public.training_course.video_file_id IS '课程视频文件标识，关联系统统一文件资源';
COMMENT ON COLUMN public.training_course.video_duration_seconds IS '视频实际时长，单位秒；必须与计划学习时长一致';
COMMENT ON COLUMN public.training_course.status IS '课程状态，字典：training_course_status';
COMMENT ON COLUMN public.training_course.is_locked IS '课程核心内容是否锁定；被执行中的培训任务使用后锁定';
COMMENT ON COLUMN public.training_course.created_by IS '创建人唯一标识';
COMMENT ON COLUMN public.training_course.created_at IS '创建时间';
COMMENT ON COLUMN public.training_course.updated_by IS '最后修改人唯一标识';
COMMENT ON COLUMN public.training_course.updated_at IS '最后修改时间';



CREATE TABLE public.exam_question (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    is_del bool NOT NULL DEFAULT false,
    question_type varchar(20) NOT NULL,
    question_text text NOT NULL,
    explanation text,
    status varchar(20) NOT NULL DEFAULT 'DRAFT',
    created_by varchar(64) NOT NULL,
    created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by varchar(64) NOT NULL,
    updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON TABLE public.exam_question IS '考试题库题目';
COMMENT ON COLUMN public.exam_question.id IS '主键，自增';
COMMENT ON COLUMN public.exam_question.is_del IS '是否删除：false-未删除，true-已删除';
COMMENT ON COLUMN public.exam_question.question_type IS '题型，字典：exam_question_type';
COMMENT ON COLUMN public.exam_question.question_text IS '题干';
COMMENT ON COLUMN public.exam_question.explanation IS '答案解析';
COMMENT ON COLUMN public.exam_question.status IS '题目状态，字典：exam_question_status';
COMMENT ON COLUMN public.exam_question.created_by IS '创建人唯一标识';
COMMENT ON COLUMN public.exam_question.created_at IS '创建时间';
COMMENT ON COLUMN public.exam_question.updated_by IS '最后修改人唯一标识';
COMMENT ON COLUMN public.exam_question.updated_at IS '最后修改时间';


CREATE TABLE public.exam_question_option (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    is_del bool NOT NULL DEFAULT false,
    question_id bigint NOT NULL,
    option_code varchar(10) NOT NULL,
    option_text text NOT NULL,
    is_correct boolean NOT NULL DEFAULT false,
    sort_order integer NOT NULL,
    CONSTRAINT uk_exam_question_option_question_code UNIQUE (question_id, option_code),
    CONSTRAINT uk_exam_question_option_question_sort UNIQUE (question_id, sort_order),
    CONSTRAINT ck_exam_question_option_sort_positive CHECK (sort_order > 0)
);

COMMENT ON TABLE public.exam_question_option IS '考试题库题目选项';
COMMENT ON COLUMN public.exam_question_option.id IS '主键，自增';
COMMENT ON COLUMN public.exam_question_option.is_del IS '是否删除：false-未删除，true-已删除';
COMMENT ON COLUMN public.exam_question_option.question_id IS '关联 exam_question.id，不创建外键';
COMMENT ON COLUMN public.exam_question_option.option_code IS '题库选项标识，如 A、B、C、D';
COMMENT ON COLUMN public.exam_question_option.option_text IS '选项内容';
COMMENT ON COLUMN public.exam_question_option.is_correct IS '是否为正确答案';
COMMENT ON COLUMN public.exam_question_option.sort_order IS '选项在题库中的默认显示顺序';

CREATE TABLE public.exam_paper (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    is_del bool NOT NULL DEFAULT false,
    paper_name varchar(200) NOT NULL,
    paper_mode varchar(20) NOT NULL,
    total_score numeric(8, 2) NOT NULL,
    random_question_order boolean NOT NULL DEFAULT false,
    random_option_order boolean NOT NULL DEFAULT false,
    single_choice_count integer,
    single_choice_score numeric(8, 2),
    multiple_choice_count integer,
    multiple_choice_score numeric(8, 2),
    true_false_count integer,
    true_false_score numeric(8, 2),
    status varchar(20) NOT NULL DEFAULT 'DRAFT',
    created_by varchar(64) NOT NULL,
    created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by varchar(64) NOT NULL,
    updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP
);

COMMENT ON TABLE public.exam_paper IS '考试试卷';
COMMENT ON COLUMN public.exam_paper.id IS '主键，自增';
COMMENT ON COLUMN public.exam_paper.is_del IS '是否删除：false-未删除，true-已删除';
COMMENT ON COLUMN public.exam_paper.paper_name IS '试卷名称';
COMMENT ON COLUMN public.exam_paper.paper_mode IS '组卷模式，字典：exam_paper_mode';
COMMENT ON COLUMN public.exam_paper.total_score IS '试卷总分';
COMMENT ON COLUMN public.exam_paper.random_question_order IS '考试时是否随机排列题目顺序';
COMMENT ON COLUMN public.exam_paper.random_option_order IS '考试时是否随机排列选项顺序';
COMMENT ON COLUMN public.exam_paper.single_choice_count IS '随机组卷时单选题抽取数量；固定组卷时为空';
COMMENT ON COLUMN public.exam_paper.single_choice_score IS '随机组卷时每道单选题分值；固定组卷时为空';
COMMENT ON COLUMN public.exam_paper.multiple_choice_count IS '随机组卷时多选题抽取数量；固定组卷时为空';
COMMENT ON COLUMN public.exam_paper.multiple_choice_score IS '随机组卷时每道多选题分值；固定组卷时为空';
COMMENT ON COLUMN public.exam_paper.true_false_count IS '随机组卷时判断题抽取数量；固定组卷时为空';
COMMENT ON COLUMN public.exam_paper.true_false_score IS '随机组卷时每道判断题分值；固定组卷时为空';
COMMENT ON COLUMN public.exam_paper.status IS '试卷状态，字典：exam_paper_status';
COMMENT ON COLUMN public.exam_paper.created_by IS '创建人唯一标识';
COMMENT ON COLUMN public.exam_paper.created_at IS '创建时间';
COMMENT ON COLUMN public.exam_paper.updated_by IS '最后修改人唯一标识';
COMMENT ON COLUMN public.exam_paper.updated_at IS '最后修改时间';



CREATE TABLE public.exam_paper_question (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    is_del bool NOT NULL DEFAULT false,
    paper_id bigint NOT NULL,
    question_id bigint NOT NULL,
    question_score numeric(8, 2) NOT NULL,
    sort_order integer NOT NULL,
    CONSTRAINT uk_exam_paper_question_paper_question UNIQUE (paper_id, question_id),
    CONSTRAINT uk_exam_paper_question_paper_sort UNIQUE (paper_id, sort_order),
    CONSTRAINT ck_exam_paper_question_score_positive CHECK (question_score > 0),
    CONSTRAINT ck_exam_paper_question_sort_positive CHECK (sort_order > 0)
);

COMMENT ON TABLE public.exam_paper_question IS '固定试卷题目明细';
COMMENT ON COLUMN public.exam_paper_question.id IS '主键，自增';
COMMENT ON COLUMN public.exam_paper_question.is_del IS '是否删除：false-未删除，true-已删除';
COMMENT ON COLUMN public.exam_paper_question.paper_id IS '关联 exam_paper.id；仅固定组卷使用，不创建外键';
COMMENT ON COLUMN public.exam_paper_question.question_id IS '关联 exam_question.id，不创建外键';
COMMENT ON COLUMN public.exam_paper_question.question_score IS '该题在试卷中的分值';
COMMENT ON COLUMN public.exam_paper_question.sort_order IS '题目在固定试卷中的默认顺序';

CREATE INDEX idx_exam_paper_question_question_id ON public.exam_paper_question (question_id);

CREATE TABLE public.training_exam (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    is_del bool NOT NULL DEFAULT false,
    exam_name varchar(200) NOT NULL,
    paper_id bigint NOT NULL,
    duration_seconds integer NOT NULL,
    pass_score numeric(8, 2) NOT NULL,
    max_attempts integer NOT NULL,
    show_correct_answer boolean NOT NULL DEFAULT false,
    show_explanation boolean NOT NULL DEFAULT false,
    status varchar(20) NOT NULL DEFAULT 'DRAFT',
    created_by varchar(64) NOT NULL,
    created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by varchar(64) NOT NULL,
    updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT ck_training_exam_duration_positive CHECK (duration_seconds > 0),
    CONSTRAINT ck_training_exam_pass_score_nonnegative CHECK (pass_score >= 0),
    CONSTRAINT ck_training_exam_max_attempts_positive CHECK (max_attempts >= 1)
);

COMMENT ON TABLE public.training_exam IS '培训考试规则';
COMMENT ON COLUMN public.training_exam.id IS '主键，自增';
COMMENT ON COLUMN public.training_exam.is_del IS '是否删除：false-未删除，true-已删除';
COMMENT ON COLUMN public.training_exam.exam_name IS '考试名称';
COMMENT ON COLUMN public.training_exam.paper_id IS '关联 exam_paper.id，不创建外键';
COMMENT ON COLUMN public.training_exam.duration_seconds IS '考试时长，单位秒';
COMMENT ON COLUMN public.training_exam.pass_score IS '考试合格分数';
COMMENT ON COLUMN public.training_exam.max_attempts IS '最大允许考试次数，包含首次考试';
COMMENT ON COLUMN public.training_exam.show_correct_answer IS '考试结束后是否允许司机查看正确答案';
COMMENT ON COLUMN public.training_exam.show_explanation IS '考试结束后是否允许司机查看答案解析';
COMMENT ON COLUMN public.training_exam.status IS '考试状态，字典：training_exam_status';
COMMENT ON COLUMN public.training_exam.created_by IS '创建人唯一标识';
COMMENT ON COLUMN public.training_exam.created_at IS '创建时间';
COMMENT ON COLUMN public.training_exam.updated_by IS '最后修改人唯一标识';
COMMENT ON COLUMN public.training_exam.updated_at IS '最后修改时间';

CREATE INDEX idx_training_exam_paper_id ON public.training_exam (paper_id);

CREATE TABLE public.training_plan (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    is_del bool NOT NULL DEFAULT false,
    plan_year integer NOT NULL,
    plan_name varchar(200) NOT NULL,
    start_at timestamptz NOT NULL,
    end_at timestamptz NOT NULL,
    frequency varchar(20) NOT NULL,
    status varchar(20) NOT NULL DEFAULT 'DRAFT',
    created_by varchar(64) NOT NULL,
    created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by varchar(64) NOT NULL,
    updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_training_plan_year UNIQUE (plan_year)
);

COMMENT ON TABLE public.training_plan IS '年度司机安全培训计划';
COMMENT ON COLUMN public.training_plan.id IS '主键，自增；年度培训计划唯一标识';
COMMENT ON COLUMN public.training_plan.is_del IS '是否删除：false-未删除，true-已删除';
COMMENT ON COLUMN public.training_plan.plan_year IS '培训计划所属自然年度；每个自然年度最多一个培训计划';
COMMENT ON COLUMN public.training_plan.plan_name IS '培训计划名称';
COMMENT ON COLUMN public.training_plan.start_at IS '计划开始时间';
COMMENT ON COLUMN public.training_plan.end_at IS '计划结束时间';
COMMENT ON COLUMN public.training_plan.frequency IS '培训频率，字典：training_plan_frequency';
COMMENT ON COLUMN public.training_plan.status IS '培训计划状态，字典：training_plan_status';
COMMENT ON COLUMN public.training_plan.created_by IS '创建人唯一标识';
COMMENT ON COLUMN public.training_plan.created_at IS '创建时间';
COMMENT ON COLUMN public.training_plan.updated_by IS '最后修改人唯一标识';
COMMENT ON COLUMN public.training_plan.updated_at IS '最后修改时间';


CREATE TABLE public.training_plan_employee_period (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    is_del bool NOT NULL DEFAULT false,
    training_id bigint NOT NULL,
    employee_id varchar(64) NOT NULL,
    effective_from timestamptz NOT NULL,
    effective_to timestamptz,
    created_by varchar(64) NOT NULL,
    created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT ck_training_plan_employee_period_range
        CHECK (effective_to IS NULL OR effective_to >= effective_from)
);

COMMENT ON TABLE public.training_plan_employee_period IS '年度培训计划司机有效期记录';
COMMENT ON COLUMN public.training_plan_employee_period.id IS '主键，自增';
COMMENT ON COLUMN public.training_plan_employee_period.is_del IS '是否删除：false-未删除，true-已删除';
COMMENT ON COLUMN public.training_plan_employee_period.training_id IS '关联 training_plan.id，不创建外键';
COMMENT ON COLUMN public.training_plan_employee_period.employee_id IS 'VMS 司机唯一标识';
COMMENT ON COLUMN public.training_plan_employee_period.effective_from IS '司机加入培训计划的生效时间';
COMMENT ON COLUMN public.training_plan_employee_period.effective_to IS '司机退出培训计划的时间；为空表示当前有效';
COMMENT ON COLUMN public.training_plan_employee_period.created_by IS '操作人唯一标识';
COMMENT ON COLUMN public.training_plan_employee_period.created_at IS '创建时间';

CREATE INDEX idx_training_plan_employee_period_training_employee
    ON public.training_plan_employee_period (training_id, employee_id);
CREATE UNIQUE INDEX uk_training_plan_employee_period_current
    ON public.training_plan_employee_period (training_id, employee_id)
    WHERE effective_to IS NULL;

CREATE TABLE public.training_task (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    is_del bool NOT NULL DEFAULT false,
    training_id bigint NOT NULL,
    task_name varchar(200) NOT NULL,
    period_key varchar(20) NOT NULL,
    period_start_at timestamptz NOT NULL,
    period_end_at timestamptz NOT NULL,
    start_at timestamptz NOT NULL,
    deadline_at timestamptz NOT NULL,
    exam_id bigint NOT NULL,
    status varchar(20) NOT NULL DEFAULT 'NOT_STARTED',
    is_locked boolean NOT NULL DEFAULT false,
    created_by varchar(64) NOT NULL,
    created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_by varchar(64) NOT NULL,
    updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_training_task_training_period UNIQUE (training_id, period_key)
);

COMMENT ON TABLE public.training_task IS '月度或季度培训任务';
COMMENT ON COLUMN public.training_task.id IS '主键，自增';
COMMENT ON COLUMN public.training_task.is_del IS '是否删除：false-未删除，true-已删除';
COMMENT ON COLUMN public.training_task.training_id IS '关联 training_plan.id，不创建外键';
COMMENT ON COLUMN public.training_task.task_name IS '培训任务名称';
COMMENT ON COLUMN public.training_task.period_key IS '培训周期标识，如 2026-08、2026-Q3';
COMMENT ON COLUMN public.training_task.period_start_at IS '所属培训周期开始时间';
COMMENT ON COLUMN public.training_task.period_end_at IS '所属培训周期结束时间';
COMMENT ON COLUMN public.training_task.start_at IS '培训任务实际开始时间';
COMMENT ON COLUMN public.training_task.deadline_at IS '培训任务截止时间';
COMMENT ON COLUMN public.training_task.exam_id IS '关联 training_exam.id；一个培训任务仅关联一个考试，不创建外键';
COMMENT ON COLUMN public.training_task.status IS '任务状态，字典：training_task_status';
COMMENT ON COLUMN public.training_task.is_locked IS '任务核心配置是否锁定；开始执行后锁定';
COMMENT ON COLUMN public.training_task.created_by IS '创建人唯一标识';
COMMENT ON COLUMN public.training_task.created_at IS '创建时间';
COMMENT ON COLUMN public.training_task.updated_by IS '最后修改人唯一标识';
COMMENT ON COLUMN public.training_task.updated_at IS '最后修改时间';

CREATE INDEX idx_training_task_exam_id ON public.training_task (exam_id);

CREATE TABLE public.training_task_course (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    is_del bool NOT NULL DEFAULT false,
    training_id bigint NOT NULL,
    training_task_id bigint NOT NULL,
    course_id bigint NOT NULL,
    sort_order integer NOT NULL,
    created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_training_task_course_task_course UNIQUE (training_task_id, course_id)
);

COMMENT ON TABLE public.training_task_course IS '培训任务课程配置';
COMMENT ON COLUMN public.training_task_course.id IS '主键，自增';
COMMENT ON COLUMN public.training_task_course.is_del IS '是否删除：false-未删除，true-已删除';
COMMENT ON COLUMN public.training_task_course.training_id IS '关联 training_plan.id，冗余保存培训计划标识，不创建外键';
COMMENT ON COLUMN public.training_task_course.training_task_id IS '关联 training_task.id，不创建外键';
COMMENT ON COLUMN public.training_task_course.course_id IS '关联 training_course.id，不创建外键';
COMMENT ON COLUMN public.training_task_course.sort_order IS '课程在培训任务中的学习顺序';
COMMENT ON COLUMN public.training_task_course.created_at IS '创建时间';

CREATE INDEX idx_training_task_course_training_id ON public.training_task_course (training_id);
CREATE INDEX idx_training_task_course_course_id ON public.training_task_course (course_id);

CREATE TABLE public.training_task_employee (
    id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    is_del bool NOT NULL DEFAULT false,
    training_id bigint NOT NULL,
    training_task_id bigint NOT NULL,
    employee_id varchar(64) NOT NULL,
    is_required boolean NOT NULL DEFAULT true,
    assigned_at timestamptz NOT NULL,
    excluded_at timestamptz,
    status varchar(30) NOT NULL DEFAULT 'NOT_STARTED',
    ever_overdue boolean NOT NULL DEFAULT false,
    overdue_at timestamptz,
    first_learning_at timestamptz,
    total_learning_seconds integer NOT NULL DEFAULT 0,
    final_employee_exam_id bigint,
    final_score numeric(8, 2),
    final_passed boolean,
    completed_at timestamptz,
    created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT uk_training_task_employee_task_employee UNIQUE (training_task_id, employee_id)
);

COMMENT ON TABLE public.training_task_employee IS '培训任务司机执行汇总';
COMMENT ON COLUMN public.training_task_employee.id IS '主键，自增';
COMMENT ON COLUMN public.training_task_employee.is_del IS '是否删除：false-未删除，true-已删除';
COMMENT ON COLUMN public.training_task_employee.training_id IS '关联 training_plan.id，冗余保存培训计划标识，不创建外键';
COMMENT ON COLUMN public.training_task_employee.training_task_id IS '关联 training_task.id，不创建外键';
COMMENT ON COLUMN public.training_task_employee.employee_id IS 'VMS 司机唯一标识';
COMMENT ON COLUMN public.training_task_employee.is_required IS '当前是否计入该培训任务应培训人员';
COMMENT ON COLUMN public.training_task_employee.assigned_at IS '司机纳入该培训任务的时间';
COMMENT ON COLUMN public.training_task_employee.excluded_at IS '司机退出该培训任务应培训范围的时间';
COMMENT ON COLUMN public.training_task_employee.status IS '司机培训状态，字典：employee_training_task_status';
COMMENT ON COLUMN public.training_task_employee.ever_overdue IS '是否曾经发生培训逾期';
COMMENT ON COLUMN public.training_task_employee.overdue_at IS '首次发生培训逾期的时间';
COMMENT ON COLUMN public.training_task_employee.first_learning_at IS '首次开始学习的时间';
COMMENT ON COLUMN public.training_task_employee.total_learning_seconds IS '该培训任务累计有效学习时长，单位秒';
COMMENT ON COLUMN public.training_task_employee.final_employee_exam_id IS '最终有效考试记录标识，关联 employee_exam.id，不创建外键';
COMMENT ON COLUMN public.training_task_employee.final_score IS '最终考试成绩';
COMMENT ON COLUMN public.training_task_employee.final_passed IS '最终考试是否合格';
COMMENT ON COLUMN public.training_task_employee.completed_at IS '培训最终完成时间';
COMMENT ON COLUMN public.training_task_employee.created_at IS '创建时间';
COMMENT ON COLUMN public.training_task_employee.updated_at IS '最后更新时间';

CREATE INDEX idx_training_task_employee_training_id ON public.training_task_employee (training_id);
CREATE INDEX idx_training_task_employee_employee_id ON public.training_task_employee (employee_id);
CREATE INDEX idx_training_task_employee_final_exam ON public.training_task_employee (final_employee_exam_id);

