-- 字典项。dict_type_id 与 dict_type_code 同时写入，适配现有字典表结构。
INSERT INTO public.sys_dict_item (
    dict_type_id,
    item_code,
    item_name,
    sort_no,
    description,
    dict_type_code,
    status
)
SELECT
    t.id,
    v.item_code,
    v.item_name,
    v.sort_no,
    v.description,
    v.dict_type_code,
    'ACTIVE'
FROM (
    VALUES
        ('training_course_status', 'DRAFT', '草稿', 10, '课程尚未启用'),
        ('training_course_status', 'ACTIVE', '启用', 20, '课程可被培训任务使用'),
        ('training_course_status', 'DISABLED', '停用', 30, '课程停止用于新的培训任务'),

        ('exam_question_type', 'SINGLE_CHOICE', '单选题', 10, '仅有一个正确选项'),
        ('exam_question_type', 'MULTIPLE_CHOICE', '多选题', 20, '包含多个正确选项'),
        ('exam_question_type', 'TRUE_FALSE', '判断题', 30, '判断陈述正确或错误'),

        ('exam_question_status', 'DRAFT', '草稿', 10, '题目尚未启用'),
        ('exam_question_status', 'ACTIVE', '启用', 20, '题目可用于组卷'),
        ('exam_question_status', 'DISABLED', '停用', 30, '题目停止用于新的组卷'),

        ('exam_paper_mode', 'FIXED', '固定组卷', 10, '使用预先配置的固定题目'),
        ('exam_paper_mode', 'RANDOM', '随机组卷', 20, '按题型数量和分值随机抽题'),

        ('exam_paper_status', 'DRAFT', '草稿', 10, '试卷尚未启用'),
        ('exam_paper_status', 'ACTIVE', '启用', 20, '试卷可被考试使用'),
        ('exam_paper_status', 'DISABLED', '停用', 30, '试卷停止用于新的考试'),

        ('training_exam_status', 'DRAFT', '草稿', 10, '考试尚未启用'),
        ('training_exam_status', 'ACTIVE', '启用', 20, '考试可被培训任务使用'),
        ('training_exam_status', 'DISABLED', '停用', 30, '考试停止用于新的培训任务'),

        ('training_plan_frequency', 'MONTHLY', '月度', 10, '按月度组织培训任务'),
        ('training_plan_frequency', 'QUARTERLY', '季度', 20, '按季度组织培训任务'),

        ('training_plan_status', 'DRAFT', '草稿', 10, '培训计划尚未发布'),
        ('training_plan_status', 'PUBLISHED', '已发布', 20, '培训计划已经发布'),

        ('training_task_status', 'NOT_STARTED', '未开始', 10, '培训任务尚未开始'),
        ('training_task_status', 'ACTIVE', '进行中', 20, '培训任务正在执行'),
        ('training_task_status', 'OVERDUE', '已逾期', 30, '培训任务已超过截止时间'),
        ('training_task_status', 'COMPLETED', '已完成', 40, '培训任务已经完成'),

        ('employee_training_task_status', 'NOT_STARTED', '未开始', 10, '司机尚未开始本次培训'),
        ('employee_training_task_status', 'LEARNING', '学习中', 20, '司机正在学习任务课程'),
        ('employee_training_task_status', 'READY_FOR_EXAM', '待考试', 30, '全部课程已完成，可以参加考试'),
        ('employee_training_task_status', 'EXAM_FAILED', '考试未通过', 40, '最近一次考试未通过且仍可能补考'),
        ('employee_training_task_status', 'OVERDUE', '已逾期', 50, '司机未在截止时间前完成培训'),
        ('employee_training_task_status', 'COMPLETED', '已完成', 60, '司机已经完成培训并通过考试'),

        ('employee_course_learning_status', 'NOT_STARTED', '未开始', 10, '课程尚未开始学习'),
        ('employee_course_learning_status', 'LEARNING', '学习中', 20, '课程正在学习'),
        ('employee_course_learning_status', 'COMPLETED', '已完成', 30, '课程已经完成学习'),

        ('employee_exam_status', 'IN_PROGRESS', '答题中', 10, '本次考试正在进行'),
        ('employee_exam_status', 'SUBMITTED', '已交卷', 20, '本次考试已经提交'),

        ('employee_exam_submit_type', 'MANUAL', '主动交卷', 10, '司机主动提交试卷'),
        ('employee_exam_submit_type', 'TIMEOUT', '超时交卷', 20, '考试到时由系统自动提交')
) AS v(dict_type_code, item_code, item_name, sort_no, description)
JOIN public.sys_dict_type t
  ON t.dict_type_code = v.dict_type_code
ON CONFLICT (dict_type_code, item_code) DO UPDATE
SET dict_type_id = EXCLUDED.dict_type_id,
    item_name = EXCLUDED.item_name,
    sort_no = EXCLUDED.sort_no,
    description = EXCLUDED.description,
    status = EXCLUDED.status,
    updated_at = CURRENT_TIMESTAMP,
    is_del = false;

COMMIT;
